items.find:
document.getElementById('agentHint').textContent = (error && error.code === 'UPSTREAM_BUSY')
  ? '食神通道排队中（免费额度并发限制），这次用本地推荐顶上，过一会儿会自动恢复。'
  : '后端暂不可用，当前使用本地推荐。配置好后会自动切换。';

items.replace:
// 把失败原因直接写出来，方便自查：地址不通 / 没配 key / 域名白名单 / 限流
const hintMap = {
  NOT_CONFIGURED: '后端没配 ZHIPU_API_KEY，去 Cloudflare 项目 Settings → Variables and Secrets 加一个 Secret。',
  RATE_LIMITED:   '问得太急了（每分钟 12 次上限），歇一分钟再试。',
  BUDGET_EXHAUSTED: '今日额度用完了，明天自动恢复。',
  UPSTREAM_BUSY:  '食神通道排队中（免费额度并发限制），过一会儿会自动恢复。'
};
const code = error && error.code;
const status = error && error.status;
document.getElementById('agentHint').textContent = hintMap[code]
  || (status
        ? '后端返回 ' + status + '：' + ((error && error.message) || '未知错误')
        : '后端地址连不上（' + ((error && error.message) || '网络错误') + '），已用本地推荐。');
